final class SshHostKeyScanner {
    static final Duration SCAN_TIMEOUT = Duration.ofSeconds(45);
    private static final int CONNECT_TIMEOUT_SECONDS = 10;
    private static final String KEYSCAN = "ssh-keyscan";
    /** OpenSSH diagnostics that mean the local client could not agree algorithms with the target. */
    private static final List<String> NEGOTIATION_FAILURES = List.of(
            "unsupported KEX method",          // Win32-OpenSSH 9.5 ssh-keyscan proposes a KEX it cannot perform
            "no matching key exchange method", // client/server KEX proposals do not intersect
            "no matching host key type",       // target offers only key types this client rejects
            "Unable to negotiate");            // OpenSSH wrapper for the two above

    private final List<String> clients;

    SshHostKeyScanner() { this(clientsOnThisMachine()); }
    SshHostKeyScanner(List<String> clients) { this.clients = List.copyOf(clients); }

    /** One scan outcome: the keys found, and — when none were — whether the client itself could not negotiate. */
    record Scan(List<String> keys, boolean clientNegotiationUnsupported) {}

    List<String> command(SshTarget target) { return command(clients.getFirst(), target); }  // hmm

    static List<String> command(String client, SshTarget target) {
        var command = new ArrayList<String>();
        command.add(client);
        target.port().ifPresent(port -> command.addAll(List.of("-p", Integer.toString(port))));
        command.addAll(List.of("-T", Integer.toString(CONNECT_TIMEOUT_SECONDS)));
        command.add(target.host());
        return List.copyOf(command);
    }

    Scan scan(ProcessRunner processes, SshTarget target) {
        boolean negotiationFailed = false;
        for (Iterator<String> it = clients.iterator(); it.hasNext(); ) {
            String client = it.next();
            ProcessRunner.Result result = processes.run(command(client, target), SCAN_TIMEOUT);
            List<String> keys = keys(result.stdout());
            if (!keys.isEmpty()) return new Scan(keys, false);
            if (!clientCouldNotNegotiate(result)) return new Scan(List.of(), false);
            negotiationFailed = true;
            if (!it.hasNext()) break;  // no further candidate
        }
        return new Scan(List.of(), negotiationFailed);
    }
```

