    /** Scripted process boundary: answers by command name, records what was asked for. */
    private static final class ScriptedRunner implements ProcessRunner {
        private final Map<String, Result> answers;
        private final List<String> asked = new ArrayList<>();

        ScriptedRunner(Map<String, Result> answers) { this.answers = answers; }

        @Override
        public Result run(List<String> command, Duration timeout) {
            asked.add(command.getFirst());
            return answers.getOrDefault(command.getFirst(), new Result(127, "", ""));
        }

        List<String> asked() { return List.copyOf(asked); }
